import { forwardRef } from "react";
import type {
  AnchorHTMLAttributes,
  ButtonHTMLAttributes,
  ComponentType,
  Ref,
} from "react";
import { cx, sortCx } from "@/lib/cx";

/**
 * Square icon-only button. Unlike `Button` (whose small size is radius/lg with
 * an 18px icon), the icon button keeps radius/2lg (10px) at both sizes:
 *
 *            container   padding   icon
 *   medium   36×36       8         20×20
 *   small    32×32       8         16×16
 *
 * Secondary controls share Button's border, shadow and state tokens.
 * Tertiary controls are circular, with the quieter surface used in dialog headers.
 */

type IconButtonSize = "medium" | "small" | "compact";
type IconButtonVariant = "secondary" | "tertiary";

type IconComponent = ComponentType<{
  className?: string;
  "aria-hidden"?: boolean | "true" | "false";
}>;

export interface IconButtonProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> {
  icon: IconComponent;
  size?: IconButtonSize;
  variant?: IconButtonVariant;
  /** Keep a composed control's own surface styles. Icon sizing and native props remain shared. */
  unstyled?: boolean;
  /** Accessible name — required since there is no visible label. */
  "aria-label": string;
  ref?: Ref<HTMLButtonElement>;
}

export interface IconLinkButtonProps
  extends Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "children"> {
  icon: IconComponent;
  size?: IconButtonSize;
  variant?: IconButtonVariant;
  /** Keep a composed control's own surface styles. Icon sizing and native props remain shared. */
  unstyled?: boolean;
  /** Accessible name — required since there is no visible label. */
  "aria-label": string;
  ref?: Ref<HTMLAnchorElement>;
}

const styles = sortCx({
  base: [
    "relative inline-flex shrink-0 items-center justify-center overflow-visible",
    "select-none cursor-pointer",
    "transition-[background-color,border-color,box-shadow,color] duration-150 ease",
    "outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring",
  ].join(" "),
  variant: {
    secondary: [
      "rounded-2lg bg-background-primary-default text-foreground-icon-primary",
      "border border-border-button-default shadow-xs focus-visible:ring-offset-2",
      "hover:bg-background-primary-hover hover:border-border-button-hover",
      "active:bg-background-primary-active active:border-border-button-active",
      "disabled:cursor-not-allowed disabled:bg-background-primary-disabled disabled:border-border-button-default disabled:text-icon-button-disabled-foreground disabled:opacity-60 disabled:shadow-none",
    ].join(" "),
    tertiary:
      "rounded-full border-0 bg-background-tertiary-default text-foreground-icon-secondary shadow-none transition-colors hover:bg-background-tertiary-hover",
  },
  size: {
    medium: "size-9",
    small: "size-8",
    compact: "size-6",
  },
  icon: {
    medium: "size-5 shrink-0",
    small: "size-4 shrink-0",
    compact: "size-4 shrink-0",
  },
});

export const IconButton = forwardRef<HTMLButtonElement, IconButtonProps>(function IconButton({
  icon: Icon,
  size = "medium",
  variant = "secondary",
  unstyled = false,
  className,
  type = "button",
  ...props
}: IconButtonProps, ref) {
  return (
    <button
      ref={ref}
      type={type}
      className={
        unstyled
          ? className
          : cx(
              styles.base,
              styles.variant[variant],
              styles.size[size],
              className,
            )
      }
      {...props}
    >
      <Icon
        className={
          unstyled
            ? styles.icon[size].replace(" shrink-0", "")
            : styles.icon[size]
        }
        aria-hidden
      />
    </button>
  );
});

/** Anchor counterpart to IconButton for external and navigational actions. */
export function IconLinkButton({
  icon: Icon,
  size = "medium",
  variant = "secondary",
  unstyled = false,
  className,
  ref,
  ...props
}: IconLinkButtonProps) {
  return (
    <a
      ref={ref}
      className={
        unstyled
          ? className
          : cx(
              styles.base,
              styles.variant[variant],
              styles.size[size],
              className,
            )
      }
      {...props}
    >
      <Icon
        className={
          unstyled
            ? styles.icon[size].replace(" shrink-0", "")
            : styles.icon[size]
        }
        aria-hidden
      />
    </a>
  );
}
